package contracttest
import("bytes";"os";"testing"; collectorv1 "github.com/h66rogi/rogi-collector/proto/gen/collector/v1"; "google.golang.org/protobuf/proto")
func TestTypeScriptWireInGo(t *testing.T){b,e:=os.ReadFile("../../contracts/fixtures/ts-donation.bin");if e!=nil{t.Fatal(e)};var got collectorv1.DonationEvent;if e=proto.Unmarshal(b,&got);e!=nil{t.Fatal(e)};if got.GetCursor().GetChannelOffset()!=^uint64(0)||got.GetConnectionSequence()!=^uint64(0)||got.GetDonationKind()!="unknown_future_kind"||got.OccurredAt!=nil||got.SourceEventId!=nil||got.ObservedAt==nil{t.Fatal("cross-language contract mismatch")};out,e:=proto.MarshalOptions{Deterministic:true}.Marshal(&got);if e!=nil||!bytes.Equal(out,b){t.Fatal("Go changed TypeScript deterministic wire")}}
func TestGoPreservesUnknownAdditiveField(t *testing.T){b,e:=os.ReadFile("../../contracts/fixtures/ts-additive.bin");if e!=nil{t.Fatal(e)};var got collectorv1.DonationEvent;if e=proto.Unmarshal(b,&got);e!=nil{t.Fatal(e)};out,e:=proto.MarshalOptions{Deterministic:true}.Marshal(&got);if e!=nil||!bytes.Equal(out,b){t.Fatal("Go discarded unknown additive field")}}
func TestTypeScriptRecoveryMaxUint64InGo(t *testing.T){b,e:=os.ReadFile("../../contracts/fixtures/ts-recovery.bin");if e!=nil{t.Fatal(e)};var got collectorv1.ResolveConsumerRecoveryResponse;if e=proto.Unmarshal(b,&got);e!=nil{t.Fatal(e)};if got.GetRecoveryRevision()!=^uint64(0)||got.GetPreviousCursor().GetChannelOffset()!=^uint64(0)||got.GetPreviousGeneration()!="old"||got.GetNewGeneration()!="new"{t.Fatal("recovery values changed across TypeScript to Go wire")}}
